import{_ as e,o as n,c as r,a0 as o}from"./chunks/framework.DScjKhBS.js";const h=JSON.parse('{"title":"Case study — billing engine enhancement","description":"Condensed walkthrough of the Fowler article’s SPDD example — multi-plan billing, model-aware pricing, prompt updates vs refactor sync.","frontmatter":{"title":"Case study — billing engine enhancement","description":"Condensed walkthrough of the Fowler article’s SPDD example — multi-plan billing, model-aware pricing, prompt updates vs refactor sync."},"headers":[],"relativePath":"reports/structured-prompt-driven/03-case-study-billing-engine.md","filePath":"reports/structured-prompt-driven/03-case-study-billing-engine.md"}'),a={name:"reports/structured-prompt-driven/03-case-study-billing-engine.md"};function s(i,t,d,l,c,g){return n(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="case-study-—-billing-engine-enhancement" tabindex="-1">Case study — billing engine enhancement <a class="header-anchor" href="#case-study-—-billing-engine-enhancement" aria-label="Permalink to &quot;Case study — billing engine enhancement&quot;">​</a></h1><p>The article walks through an <strong>end-to-end</strong> SPDD example: enhancing a <strong>token billing engine</strong> for an LLM API — small enough to read, complete enough to show analysis → Canvas → code → tests. Artifacts and commands are illustrated with <strong>open-spdd</strong>; the <strong>initial system</strong> and <strong>enhancement diff</strong> are published on GitHub (links in the <a href="https://martinfowler.com/articles/structured-prompt-driven/" target="_blank" rel="noreferrer">primary article</a>).</p><p>This page <strong>does not</strong> reproduce full prompts or code — it extracts the <strong>process pattern</strong> for teams evaluating SPDD.</p><hr><h2 id="business-thrust" tabindex="-1">Business thrust <a class="header-anchor" href="#business-thrust" aria-label="Permalink to &quot;Business thrust&quot;">​</a></h2><p>The enhancement moves from a <strong>static</strong> pricing model to:</p><ul><li><strong>API:</strong> <code>POST /api/usage</code> gains required <strong><code>modelId</code></strong> (e.g. <code>fast-model</code>, <code>reasoning-model</code>).</li><li><strong>Pricing:</strong> <strong>Model-aware</strong> rates instead of one global rate.</li><li><strong>Plans:</strong> e.g. <strong>Standard</strong> (quota + model-specific overage) vs <strong>Premium</strong> (no quota; <strong>split</strong> prompt/completion billing per model).</li><li><strong>Architecture:</strong> Extensible pattern (e.g. Strategy / Factory) for future plans.</li></ul><hr><h2 id="step-pattern-mapped-to-commands" tabindex="-1">Step pattern (mapped to commands) <a class="header-anchor" href="#step-pattern-mapped-to-commands" aria-label="Permalink to &quot;Step pattern (mapped to commands)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Activity</th><th>SPDD idea</th></tr></thead><tbody><tr><td>1</td><td>User story / requirements</td><td>Optional <code>/spdd-story</code>; consolidate ACs (Given/When/Then)</td></tr><tr><td>2</td><td>Clarify analysis</td><td>Human alignment — core logic, scope boundaries, DoD scenarios</td></tr><tr><td>3</td><td>Analysis context</td><td><code>/spdd-analysis</code> — targeted codebase scan, risks, direction</td></tr><tr><td>4</td><td>Structured prompt</td><td><code>/spdd-reasons-canvas</code> — full REASONS blueprint</td></tr><tr><td>5</td><td>Code + API tests</td><td><code>/spdd-generate</code>; optional <code>/spdd-api-test</code>; run script (e.g. <code>sh scripts/test-api.sh</code>)</td></tr><tr><td>6</td><td>Unit tests</td><td>Template-driven test prompts where dedicated commands are still evolving</td></tr></tbody></table><hr><h2 id="prompt-maintenance-article-behaviour" tabindex="-1">Prompt maintenance (article behaviour) <a class="header-anchor" href="#prompt-maintenance-article-behaviour" aria-label="Permalink to &quot;Prompt maintenance (article behaviour)&quot;">​</a></h2><ul><li><strong>Preferred:</strong> avoid manually hacking the Canvas in isolation — use <strong>dialogue</strong> with the AI so only affected sections change.</li><li><strong>Behaviour change:</strong> <code>/spdd-prompt-update</code> then <code>/spdd-generate</code> for <strong>targeted</strong> updates (example: <code>modelId</code> mandatory with default <code>fast-model</code> after business confirmation).</li><li><strong>Refactor only:</strong> e.g. extract <strong>magic numbers</strong> to constants in code, then <strong><code>/spdd-sync</code></strong> so the Canvas stays an accurate design document.</li></ul><p>The article explicitly cites <strong>Martin Fowler’s</strong> definition of refactoring: internal structure change <strong>without</strong> observable behaviour change — hence <strong>sync</strong>, not prompt-first regeneration.</p><hr><h2 id="outcomes-claimed-in-the-article" tabindex="-1">Outcomes claimed in the article <a class="header-anchor" href="#outcomes-claimed-in-the-article" aria-label="Permalink to &quot;Outcomes claimed in the article&quot;">​</a></h2><p>Strong <strong>intent alignment</strong>, transparent engineering decisions, a <strong>Canvas synchronized</strong> with the codebase, and <strong>compounding</strong> domain knowledge across iterations — with the caveat that SPDD aims at <strong>reliable</strong> delivery, not always the shortest path to raw generation speed.</p><hr><p><strong>Previous:</strong> <a href="./reports/structured-prompt-driven/02-openspdd-and-workflow.html">Workflow &amp; openspdd</a> · <strong>Next:</strong> <a href="./reports/structured-prompt-driven/04-skills-fitness-and-trade-offs.html">Skills, fitness &amp; trade-offs</a></p>',19)])])}const m=e(a,[["render",s]]);export{h as __pageData,m as default};
